import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, X, WifiOff, StopCircle, Sparkles, Trash2 } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

// مكون إعلان شفاف
// يظهر فقط المحتوى (الإعلان) وزر إغلاق صغير، بدون خلفيات معتمة
const TransparentAdOverlay = ({ onClose }: { onClose: () => void }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    containerRef.current.innerHTML = '';

    const iframe = document.createElement('iframe');
    iframe.setAttribute('sandbox', 'allow-scripts allow-popups allow-same-origin allow-forms allow-top-navigation allow-presentation');

    // الأبعاد الجديدة 300x250
    iframe.style.width = '300px';
    iframe.style.height = '250px';
    iframe.style.border = 'none';
    iframe.style.overflow = 'hidden';

    containerRef.current.appendChild(iframe);

    const doc = iframe.contentWindow?.document;
    if (doc) {
      doc.open();
      // خلفية شفافة للجسم داخل الـ iframe
      doc.write(`
        <!DOCTYPE html>
        <html>
          <body style="margin:0;padding:0;background:transparent;display:flex;justify-content:center;align-items:center;">
            <script type="text/javascript">
              atOptions = {
                'key' : '4a0d8e1893965feae543e88f409ee5f7',
                'format' : 'iframe',
                'height' : 250,
                'width' : 300,
                'params' : {}
              };
            </script>
            <script type="text/javascript" src="//www.highperformanceformat.com/4a0d8e1893965feae543e88f409ee5f7/invoke.js"></script>
          </body>
        </html>
      `);
      doc.close();
    }
  }, []);

  return (
    // وضع الإعلان في المنتصف ليكون واضحاً كـ Interstitial
    <div className="fixed inset-0 z-[100] flex justify-center items-center pointer-events-none">
      <div className="relative pointer-events-auto animate-in zoom-in-95 fade-in duration-300 bg-[#212121] rounded-lg shadow-2xl p-1 border border-white/10">

        {/* زر إغلاق */}
        <button 
          onClick={onClose} 
          className="absolute -right-3 -top-3 bg-red-600 text-white rounded-full p-1.5 shadow-lg hover:bg-red-700 transition-colors z-50"
          title="إغلاق الإعلان"
        >
          <X size={16} />
        </button>

        {/* حاوية الإعلان */}
        <div ref={containerRef} className="rounded overflow-hidden min-h-[250px] min-w-[300px] bg-black/20">
           {/* سيتم تحميل الإعلان 300x250 هنا */}
        </div>
      </div>
    </div>
  );
};

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

