  if (firebaseConfig.apiKey && firebaseConfig.apiKey !== "") {
    app = initializeApp(firebaseConfig);
    auth = getAuth(app);
    googleProvider = new GoogleAuthProvider();
    db = getFirestore(app);
  } else {
