import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, X, WifiOff, StopCircle, Sparkles, Trash2, Heart, LogIn, LogOut, Menu, Plus, MessageSquare, History, AlertTriangle } from 'lucide-react';
import { Message, Role, UserProfile, ChatSession } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

// Firebase Imports
import { auth, googleProvider, db } from './firebaseConfig';
import { signInWithPopup, signOut, onAuthStateChanged, User } from 'firebase/auth';
import { collection, addDoc, query, where, orderBy, onSnapshot, doc, updateDoc, serverTimestamp, getDoc } from 'firebase/firestore';

function App() {
  // Authentication State
  const [user, setUser] = useState<User | any | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [configError, setConfigError] = useState(false);
  const [isGuest, setIsGuest] = useState(false);

  // Chat State
  const [messages, setMessages] = useState<Message[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // UI State
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Modals & Ads
  const [showWelcomeModal, setShowWelcomeModal] = useState(false); // Default false, shown after login logic if needed
  const [adRefreshKey, setAdRefreshKey] = useState(0);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  // --- Authentication Monitor ---
  useEffect(() => {
    if (!auth || !db) {
      console.warn("Firebase Auth or DB not initialized. App will run in Guest Mode.");
      setConfigError(true);
      setAuthLoading(false);
      return;
    }

    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
      if (currentUser) {
        // Load user's chat history
        const q = query(
          collection(db!, "chats"), 
          where("userId", "==", currentUser.uid),
          orderBy("updatedAt", "desc")
        );
        const unsubscribeChats = onSnapshot(q, (snapshot) => {
          const history = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          } as ChatSession));
          setChatHistory(history);
        }, (error) => {
           console.error("Error fetching chats:", error);
        });
        return () => unsubscribeChats();
      } else {
        setChatHistory([]);
        setMessages([]);
        setCurrentChatId(null);
      }
    });
    return () => unsubscribe();
  }, []);

  // --- Network Monitor ---
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- Ad Timer ---
  useEffect(() => {
    const interval = setInterval(() => {
      setAdRefreshKey(prev => prev + 1);
    }, 30000); 
    return () => clearInterval(interval);
  }, []);

  // --- Auto Scroll ---
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isLoading]);

  // --- Handlers ---

  const handleLogin = async () => {
    if (!auth || !googleProvider) {
      // Guest Login Fallback
      const guestUser = {
        uid: 'guest-' + Date.now(),
        displayName: 'Guest User',
        email: null,
        photoURL: null,
        isAnonymous: true
      };
      setIsGuest(true);
      setUser(guestUser);
      return;
    }
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (error) {
      console.error("Login failed", error);
      alert("فشل تسجيل الدخول. يرجى المحاولة مرة أخرى.");
    }
  };

  const handleLogout = async () => {
    if (window.confirm("هل أنت متأكد من تسجيل الخروج؟")) {
      if (auth) {
        await signOut(auth);
      } else {
        setUser(null);
        setIsGuest(false);
        setMessages([]);
        setChatHistory([]);
      }
    }
  };

  const createNewChat = () => {
    setMessages([]);
    setCurrentChatId(null);
    setIsSidebarOpen(false);
    if (textareaRef.current) textareaRef.current.focus();
  };

  const loadChat = (session: ChatSession) => {
    setCurrentChatId(session.id);
    setMessages(session.messages);
    setIsSidebarOpen(false);
  };

  const deleteChat = async (e: React.MouseEvent, chatId: string) => {
    e.stopPropagation();
    if (window.confirm("هل تريد حذف هذه المحادثة نهائياً؟")) {
       try {
         if (db && !isGuest) {
             // await deleteDoc(doc(db, "chats", chatId)); 
             console.log("Delete requested for", chatId);
         }
       } catch (err) {
         console.error(err);
       }
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const saveChatToFirebase = async (updatedMessages: Message[], newMsgText: string) => {
    // If in guest mode or db not available, skip saving
    if (!user || !db || isGuest) return;

    try {
      if (!currentChatId) {
        // Create new chat document
        const title = newMsgText.length > 30 ? newMsgText.substring(0, 30) + "..." : newMsgText;
        const docRef = await addDoc(collection(db, "chats"), {
          userId: user.uid,
          title: title,
          messages: updatedMessages,
          createdAt: Date.now(),
          updatedAt: Date.now()
        });
        setCurrentChatId(docRef.id);
      } else {
        // Update existing chat
        const chatRef = doc(db, "chats", currentChatId);
        await updateDoc(chatRef, {
          messages: updatedMessages,
          updatedAt: Date.now()
        });
      }
    } catch (error) {
      console.error("Error saving chat:", error);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    if (!isOnline) return;

    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    // 1. Add User Message
    const userMsg: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    const updatedMessages = [...messages, userMsg];
    setMessages(updatedMessages);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

    setIsLoading(true);
    abortControllerRef.current = new AbortController();

    // Optimistic Save (Initial user message)
    if (user) saveChatToFirebase(updatedMessages, textToSend);

    try {
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;
      let finalBotText = "";

      await sendMessageToNZGPT(
        updatedMessages, 
        textToSend,
        (streamedText) => {
           finalBotText = streamedText;
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             setMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, text: streamedText, timestamp: Date.now() }]);
             isFirstChunk = false;
           } else {
             setMessages(prev => prev.map(msg => msg.id === botMsgId ? { ...msg, text: streamedText } : msg));
           }
        },
        tempImage || undefined,
        abortControllerRef.current.signal
      );

      // Final Save (Include Bot Response)
      if (user) {
        const messagesWithBot = [...updatedMessages, { id: botMsgId, role: Role.MODEL, text: finalBotText, timestamp: Date.now() }];
        saveChatToFirebase(messagesWithBot, textToSend);
      }

    } catch (error: any) {
      if (error.name !== 'AbortError') {
        setMessages(prev => [...prev, { id: Date.now().toString(), role: Role.MODEL, text: "خطأ في الاتصال. تأكد من جودة الإنترنت.", timestamp: Date.now() }]);
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };


  // --- Render: Login Screen ---
  if (authLoading) {
    return <div className="h-screen w-screen bg-[#212121] flex items-center justify-center"><div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div></div>;
  }

  if (!user) {
    return (
      <div className="flex flex-col h-screen w-screen bg-[#212121] items-center justify-center p-6 relative overflow-hidden">
        {/* Background Elements */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-emerald-500/10 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 rounded-full blur-[100px]"></div>
        </div>

        <div className="z-10 bg-[#2a2a2a] border border-white/5 p-8 rounded-[32px] shadow-2xl max-w-md w-full text-center">
          <div className="w-20 h-20 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-[24px] mx-auto mb-6 flex items-center justify-center shadow-lg transform rotate-3">
             <Sparkles className="text-white w-10 h-10" />
          </div>

          <h1 className="text-3xl font-black text-white mb-2 tracking-tighter">NZ GPT PRO</h1>
          <p className="text-gray-400 mb-8 font-medium">
             {configError ? "وضع الزائر متاح" : "سجل الدخول للمتابعة وحفظ محادثاتك بأمان"}
          </p>

          {configError && (
            <div className="bg-amber-500/10 border border-amber-500/20 text-amber-200 text-sm p-4 rounded-xl mb-6 text-right flex flex-col items-start gap-2">
              <div className="flex items-center gap-2">
                 <AlertTriangle size={18} className="shrink-0" />
                 <span className="font-bold">تنبيه:</span>
              </div>
              <p className="text-xs leading-relaxed opacity-90">
                لم يتم ربط قاعدة البيانات (Firebase) بشكل صحيح. يمكنك استخدام التطبيق، ولكن <b>لن يتم حفظ سجل المحادثات</b> عند الخروج.
              </p>
            </div>
          )}

          <button 
            onClick={handleLogin}
            className={`w-full font-bold py-4 px-6 rounded-2xl flex items-center justify-center gap-3 transition-all transform shadow-xl hover:bg-gray-50 active:scale-95 ${configError ? 'bg-amber-500 hover:bg-amber-400 text-black' : 'bg-white text-gray-900'}`}
          >
            {configError ? (
                <>
                 <LogIn className="w-6 h-6" />
                 الدخول كزائر (بدون حفظ)
                </>
            ) : (
                <>
                <svg className="w-6 h-6" viewBox="0 0 24 24">
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                </svg>
                المتابعة باستخدام Google
                </>
            )}
          </button>

          <p className="mt-6 text-xs text-gray-600">
            باستخدامك للتطبيق، أنت توافق على شروط الاستخدام وسياسة الخصوصية.
          </p>
        </div>
      </div>
    );
  }

  // --- Render: Main App ---
  return (
    <div className="flex h-screen w-screen bg-[#212121] text-gray-100 overflow-hidden relative">

      {/* Sidebar Overlay (Mobile) */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-sm"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed md:relative inset-y-0 right-0 z-50 w-72 bg-[#171717] border-l border-white/5 flex flex-col transition-transform duration-300 ease-in-out
        ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        md:w-64 lg:w-72 shrink-0
      `}>

        {/* Sidebar Header */}
        <div className="p-4 border-b border-white/5 flex items-center justify-between">
           <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center">
               <Sparkles size={16} className="text-white" />
             </div>
             <h2 className="font-bold text-lg tracking-tight">NZ GPT</h2>
           </div>
           <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400">
             <X size={20} />
           </button>
        </div>

        {/* New Chat Button */}
        <div className="p-4">
          <button 
            onClick={createNewChat}
            className="w-full flex items-center gap-3 bg-white/5 hover:bg-white/10 border border-white/5 text-white p-3 rounded-xl transition-all active:scale-95 group"
          >
            <div className="bg-emerald-500/20 p-1.5 rounded-lg text-emerald-500 group-hover:text-emerald-400 group-hover:bg-emerald-500/30 transition-colors">
              <Plus size={18} />
            </div>
            <span className="font-medium">محادثة جديدة</span>
          </button>
        </div>

        {/* Chat History List */}
        <div className="flex-1 overflow-y-auto px-2 py-2 space-y-1">
          <h3 className="px-4 text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 mt-2">السجل</h3>
          {isGuest ? (
             <div className="text-center py-10 opacity-30 flex flex-col items-center">
               <AlertTriangle size={32} className="mb-2 text-amber-500" />
               <span className="text-xs">السجل غير متاح في وضع الزائر</span>
             </div>
          ) : chatHistory.length === 0 ? (
             <div className="text-center py-10 opacity-30 flex flex-col items-center">
               <History size={32} className="mb-2" />
               <span className="text-xs">لا توجد محادثات سابقة</span>
             </div>
          ) : (
            chatHistory.map(chat => (
              <button
                key={chat.id}
                onClick={() => loadChat(chat)}
                className={`w-full text-right p-3 rounded-xl text-sm flex items-center gap-3 transition-all group ${currentChatId === chat.id ? 'bg-white/10 text-white font-medium' : 'text-gray-400 hover:bg-white/5 hover:text-gray-200'}`}
              >
                <MessageSquare size={16} className={currentChatId === chat.id ? 'text-emerald-500' : 'text-gray-600'} />
                <span className="truncate flex-1">{chat.title || 'محادثة بدون عنوان'}</span>
              </button>
            ))
          )}
        </div>

        {/* User Profile Footer */}
        <div className="p-4 bg-[#1a1a1a] border-t border-white/5">
          <div className="flex items-center gap-3 mb-3">
            <img 
              src={user.photoURL || "https://ui-avatars.com/api/?name=" + (isGuest ? "Guest" : "User") + "&background=random"} 
              alt="Profile" 
              className="w-10 h-10 rounded-full border border-white/10"
            />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-bold text-white truncate">{user.displayName || "مستخدم"}</p>
              <p className="text-xs text-gray-500 truncate">{isGuest ? "حساب زائر" : user.email}</p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2 text-red-400 hover:text-red-300 bg-red-500/10 hover:bg-red-500/20 py-2.5 rounded-lg text-xs font-bold transition-colors"
          >
            <LogOut size={14} />
