            <h1 className="font-black text-xl tracking-tighter md:hidden">NZ GPT</h1>
            <span className="hidden md:block font-bold text-gray-500 text-sm">
              {currentChatId ? 'محادثة الحالية' : 'محادثة جديدة'}
