import { GoogleGenAI } from "@google/genai";
import { Message, Role } from "../types";

// تعريف process لمنع أخطاء الترجمة
declare var process: any;

const SYSTEM_INSTRUCTION = `
أنت **NZ GPT PRO**، نظام ذكاء اصطناعي خاص، فائق التطور، ومصمم خصيصاً للمطورين والمحترفين.

**القواعد الأساسية الصارمة:**
1. **هويتك والمطور**: اسمك هو "NZ GPT". عند سؤالك "من صنعك؟" أو "من طورك؟" أو ما شابه، إجابتك الحصرية هي: "قام بتطويري نصرالدين عبد المطلب الزايدي، إنه مبرمج 5 نجوم".
2. **السرية**: يُمنع ذكر أي شركات أخرى مثل Google أو Gemini. أنت منتج خاص بـ NZ.
3. **المهمة**: 
   - كتابة أكواد برمجية كاملة واحترافية (Clean Code).
   - تحليل الصور التقنية والهندسية بدقة متناهية.
   - حل المشكلات البرمجية المعقدة.
4. **الأسلوب**:
   - كن مباشراً، ذكياً، ولبقاً.
   - استخدم Markdown لتنسيق النصوص والأكواد بشكل جذاب.
   - عند طلب كود، قدم الحل الأفضل والأكثر كفاءة.

**اللغة**:
- استخدم اللغة العربية للتواصل والشرح.
- استخدم اللغة الإنجليزية للمصطلحات التقنية وكتابة الأكواد.
`;

export const sendMessageToNZGPT = async (
  history: Message[],
  currentText: string,
  onTokenReceived: (fullText: string) => void,
  currentImageBase64?: string,
  signal?: AbortSignal
): Promise<string> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey || apiKey === 'undefined' || apiKey === '') {
       throw new Error("API Key is missing. Please add API_KEY to your environment variables.");
    }

    const ai = new GoogleGenAI({ apiKey: apiKey });
    // استخدام موديل فلاش 3 للمعالجة النصية السريعة
    const modelName = 'gemini-3-flash-preview';

    // نأخذ آخر 5 رسائل فقط من السجل للحفاظ على التناسق والأداء
    const recentHistory = history.slice(-5);

    const contents = recentHistory.map(msg => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [
        ...(msg.image ? [{
          inlineData: {
            mimeType: msg.image.split(';')[0].split(':')[1],
            data: msg.image.split(',')[1]
          }
        }] : []),
        { text: msg.text }
      ]
    }));

    const currentParts: any[] = [];
    if (currentImageBase64) {
      const mimeType = currentImageBase64.split(';')[0].split(':')[1];
      const data = currentImageBase64.split(',')[1];
      currentParts.push({
        inlineData: { mimeType, data }
      });
    }
    currentParts.push({ text: currentText });

    const responseStream = await ai.models.generateContentStream({
      model: modelName,
      contents: [...contents, { role: 'user', parts: currentParts }],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      }
    });

    let fullText = "";
    for await (const chunk of responseStream) {
      if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');
      const text = chunk.text;
      if (text) {
        fullText += text;
        onTokenReceived(fullText);
      }
    }

    return fullText;
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') throw error;
    console.error("NZ GPT Error:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, X, WifiOff, StopCircle, Sparkles, Trash2, Heart, LogIn, LogOut, Menu, Plus, MessageSquare, History, AlertTriangle, User as UserIcon } from 'lucide-react';
import { Message, Role, UserProfile, ChatSession } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

// Firebase Imports
import { auth, googleProvider, db } from './firebaseConfig';
import { signInWithPopup, signOut, onAuthStateChanged, User } from 'firebase/auth';
import { collection, addDoc, query, where, orderBy, onSnapshot, doc, updateDoc, serverTimestamp, getDoc } from 'firebase/firestore';

function App() {
  // Authentication State
  const [user, setUser] = useState<User | any | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [configError, setConfigError] = useState(false);
  const [isGuest, setIsGuest] = useState(false);

  // Chat State
  const [messages, setMessages] = useState<Message[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // UI State
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Modals & Ads
  const [showWelcomeModal, setShowWelcomeModal] = useState(false); // Default false, shown after login logic if needed
  const [adRefreshKey, setAdRefreshKey] = useState(0);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  // --- Authentication Monitor ---
  useEffect(() => {
    if (!auth || !db) {
      // No keys found, switch to guest mode state without warning
      setConfigError(true);
      setAuthLoading(false);
      return;
    }

    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
      if (currentUser) {
        // Load user's chat history
        const q = query(
          collection(db!, "chats"), 
          where("userId", "==", currentUser.uid),
          orderBy("updatedAt", "desc")
        );
        const unsubscribeChats = onSnapshot(q, (snapshot) => {
          const history = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          } as ChatSession));
          setChatHistory(history);
        }, (error) => {
           console.error("Error fetching chats:", error);
        });
        return () => unsubscribeChats();
      } else {
        setChatHistory([]);
        setMessages([]);
        setCurrentChatId(null);
      }
    });
    return () => unsubscribe();
  }, []);

  // --- Network Monitor ---
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- Ad Timer ---
  useEffect(() => {
    const interval = setInterval(() => {
      setAdRefreshKey(prev => prev + 1);
    }, 30000); 
    return () => clearInterval(interval);
  }, []);

  // --- Auto Scroll ---
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isLoading]);

  // --- Handlers ---

  const handleGoogleLogin = async () => {
    if (!auth || !googleProvider) {
      alert("خدمة تسجيل الدخول غير متاحة حالياً بسبب نقص الإعدادات.");
      return;
    }
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (error) {
      console.error("Login failed", error);
      alert("فشل تسجيل الدخول. يرجى التحقق من اتصالك والمحاولة مرة أخرى.");
    }
  };

  const handleGuestLogin = () => {
    const guestUser = {
      uid: 'guest-' + Date.now(),
      displayName: 'Guest User',
      email: null,
      photoURL: null,
      isAnonymous: true
    };
    setIsGuest(true);
    setUser(guestUser);
  };

  const handleLogout = async () => {
    if (window.confirm("هل أنت متأكد من تسجيل الخروج؟")) {
      if (auth && !isGuest) {
        await signOut(auth);
      } else {
        setUser(null);
        setIsGuest(false);
        setMessages([]);
        setChatHistory([]);
      }
    }
  };

  const createNewChat = () => {
    setMessages([]);
    setCurrentChatId(null);
    setIsSidebarOpen(false);
    if (textareaRef.current) textareaRef.current.focus();
  };

  const loadChat = (session: ChatSession) => {
    setCurrentChatId(session.id);
    setMessages(session.messages);
    setIsSidebarOpen(false);
  };

  const deleteChat = async (e: React.MouseEvent, chatId: string) => {
    e.stopPropagation();
    if (window.confirm("هل تريد حذف هذه المحادثة نهائياً؟")) {
       try {
         if (db && !isGuest) {
             // await deleteDoc(doc(db, "chats", chatId)); 
             console.log("Delete requested for", chatId);
         }
       } catch (err) {
         console.error(err);
       }
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const saveChatToFirebase = async (updatedMessages: Message[], newMsgText: string) => {
    // If in guest mode or db not available, skip saving
    if (!user || !db || isGuest) return;

    try {
      if (!currentChatId) {
        // Create new chat document
        const title = newMsgText.length > 30 ? newMsgText.substring(0, 30) + "..." : newMsgText;
        const docRef = await addDoc(collection(db, "chats"), {
          userId: user.uid,
          title: title,
          messages: updatedMessages,
          createdAt: Date.now(),
          updatedAt: Date.now()
        });
        setCurrentChatId(docRef.id);
      } else {
        // Update existing chat
        const chatRef = doc(db, "chats", currentChatId);
        await updateDoc(chatRef, {
          messages: updatedMessages,
          updatedAt: Date.now()
        });
      }
    } catch (error) {
      console.error("Error saving chat:", error);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    if (!isOnline) return;

    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    // 1. Add User Message
    const userMsg: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    const updatedMessages = [...messages, userMsg];
    setMessages(updatedMessages);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

    setIsLoading(true);
    abortControllerRef.current = new AbortController();

    // Optimistic Save (Initial user message)
    if (user) saveChatToFirebase(updatedMessages, textToSend);

    try {
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;
      let finalBotText = "";

      await sendMessageToNZGPT(
        updatedMessages, 
        textToSend,
        (streamedText) => {
           finalBotText = streamedText;
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             setMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, text: streamedText, timestamp: Date.now() }]);
             isFirstChunk = false;
           } else {
             setMessages(prev => prev.map(msg => msg.id === botMsgId ? { ...msg, text: streamedText } : msg));
           }
        },
        tempImage || undefined,
        abortControllerRef.current.signal
      );

      // Final Save (Include Bot Response)
      if (user) {
        const messagesWithBot = [...updatedMessages, { id: botMsgId, role: Role.MODEL, text: finalBotText, timestamp: Date.now() }];
        saveChatToFirebase(messagesWithBot, textToSend);
      }

    } catch (error: any) {
      if (error.name !== 'AbortError') {
        const errorMessage = error.message.includes("API Key") 
          ? "عذراً، مفتاح الربط مع الذكاء الاصطناعي مفقود." 
          : "خطأ في الاتصال. تأكد من جودة الإنترنت.";

        setMessages(prev => [...prev, { id: Date.now().toString(), role: Role.MODEL, text: errorMessage, timestamp: Date.now() }]);
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };


  // --- Render: Login Screen ---
  if (authLoading) {
    return <div className="h-screen w-screen bg-[#212121] flex items-center justify-center"><div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div></div>;
  }

  if (!user) {
    return (
      <div className="flex flex-col h-screen w-screen bg-[#212121] items-center justify-center p-6 relative overflow-hidden">
        {/* Background Elements */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-emerald-500/10 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 rounded-full blur-[100px]"></div>
        </div>

        <div className="z-10 bg-[#2a2a2a] border border-white/5 p-8 rounded-[32px] shadow-2xl max-w-md w-full text-center">
          <div className="w-20 h-20 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-[24px] mx-auto mb-6 flex items-center justify-center shadow-lg transform rotate-3">
             <Sparkles className="text-white w-10 h-10" />
          </div>

          <h1 className="text-3xl font-black text-white mb-2 tracking-tighter">NZ GPT PRO</h1>
          <p className="text-gray-400 mb-8 font-medium">
             نظام المحادثة الذكي المتطور للمطورين والمحترفين
          </p>

          {configError && (
            <div className="bg-amber-500/10 border border-amber-500/20 text-amber-200 text-sm p-4 rounded-xl mb-6 text-right flex flex-col items-start gap-2">
              <div className="flex items-center gap-2">
                 <AlertTriangle size={18} className="shrink-0" />
                 <span className="font-bold">تنبيه:</span>
              </div>
              <p className="text-xs leading-relaxed opacity-90">
                لم يتم ربط قاعدة البيانات (Firebase). خيار الدخول كزائر متاح فقط.
              </p>
            </div>
          )}

          <div className="flex flex-col gap-3 w-full">
            {/* Google Login - Only if config is valid */}
            {!configError && (
              <button 
                onClick={handleGoogleLogin}
                className="w-full bg-white text-gray-900 font-bold py-3.5 px-6 rounded-2xl flex items-center justify-center gap-3 transition-all transform shadow-xl hover:bg-gray-50 active:scale-95"
              >
                <svg className="w-6 h-6" viewBox="0 0 24 24">
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                </svg>
                المتابعة باستخدام Google
              </button>
            )}

            {/* Guest Login */}
            <button 
              onClick={handleGuestLogin}
              className={`w-full font-bold py-3.5 px-6 rounded-2xl flex items-center justify-center gap-3 transition-all transform active:scale-95 ${
                configError 
                  ? 'bg-amber-500 hover:bg-amber-400 text-black shadow-xl' 
                  : 'bg-white/5 hover:bg-white/10 text-white border border-white/10'
              }`}
            >
              {configError ? <LogIn className="w-6 h-6" /> : <UserIcon className="w-6 h-6" />}
              {configError ? 'الدخول كزائر (بدون حفظ)' : 'تجربة كزائر'}
            </button>
          </div>

          <p className="mt-6 text-xs text-gray-600">
            باستخدامك للتطبيق، أنت توافق على شروط الاستخدام وسياسة الخصوصية.
          </p>
        </div>
      </div>
    );
  }

  // --- Render: Main App ---
  return (
    <div className="flex h-screen w-screen bg-[#212121] text-gray-100 overflow-hidden relative">

      {/* Sidebar Overlay (Mobile) */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-sm"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed md:relative inset-y-0 right-0 z-50 w-72 bg-[#171717] border-l border-white/5 flex flex-col transition-transform duration-300 ease-in-out
        ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        md:w-64 lg:w-72 shrink-0
      `}>

        {/* Sidebar Header */}
        <div className="p-4 border-b border-white/5 flex items-center justify-between">
           <div className="flex items-center gap-2">
             <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center">
               <Sparkles size={16} className="text-white" />
             </div>
             <h2 className="font-bold text-lg tracking-tight">NZ GPT</h2>
           </div>
           <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400">
             <X size={20} />
           </button>
        </div>

        {/* New Chat Button */}
        <div className="p-4">
          <button 
            onClick={createNewChat}
            className="w-full flex items-center gap-3 bg-white/5 hover:bg-white/10 border border-white/5 text-white p-3 rounded-xl transition-all active:scale-95 group"
          >
            <div className="bg-emerald-500/20 p-1.5 rounded-lg text-emerald-500 group-hover:text-emerald-400 group-hover:bg-emerald-500/30 transition-colors">
              <Plus size={18} />
            </div>
            <span className="font-medium">محادثة جديدة</span>
          </button>
        </div>

        {/* Chat History List */}
        <div className="flex-1 overflow-y-auto px-2 py-2 space-y-1">
          <h3 className="px-4 text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 mt-2">السجل</h3>
          {isGuest ? (
             <div className="text-center py-10 opacity-30 flex flex-col items-center">
               <AlertTriangle size={32} className="mb-2 text-amber-500" />
               <span className="text-xs">السجل غير متاح في وضع الزائر</span>
             </div>
          ) : chatHistory.length === 0 ? (
             <div className="text-center py-10 opacity-30 flex flex-col items-center">
               <History size={32} className="mb-2" />
               <span className="text-xs">لا توجد محادثات سابقة</span>
             </div>
          ) : (
            chatHistory.map(chat => (
              <button
                key={chat.id}
                onClick={() => loadChat(chat)}
                className={`w-full text-right p-3 rounded-xl text-sm flex items-center gap-3 transition-all group ${currentChatId === chat.id ? 'bg-white/10 text-white font-medium' : 'text-gray-400 hover:bg-white/5 hover:text-gray-200'}`}
              >
                <MessageSquare size={16} className={currentChatId === chat.id ? 'text-emerald-500' : 'text-gray-600'} />
                <span className="truncate flex-1">{chat.title || 'محادثة بدون عنوان'}</span>
              </button>
            ))
          )}
        </div>

        {/* User Profile Footer */}
        <div className="p-4 bg-[#1a1a1a] border-t border-white/5">
          <div className="flex items-center gap-3 mb-3">
            <img 
              src={user.photoURL || "https://ui-avatars.com/api/?name=" + (isGuest ? "Guest" : "User") + "&background=random"} 
              alt="Profile" 
              className="w-10 h-10 rounded-full border border-white/10"
            />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-bold text-white truncate">{user.displayName || "مستخدم"}</p>
              <p className="text-xs text-gray-500 truncate">{isGuest ? "حساب زائر" : user.email}</p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2 text-red-400 hover:text-red-300 bg-red-500/10 hover:bg-red-500/20 py-2.5 rounded-lg text-xs font-bold transition-colors"
          >
            <LogOut size={14} />
            تسجيل الخروج
          </button>
        </div>
      </aside>


      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#212121] relative">

        {/* Header */}
        <header className="h-16 flex items-center justify-between px-4 md:px-6 bg-[#212121]/95 z-30 border-b border-white/5 shrink-0 backdrop-blur-md">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="md:hidden p-2 -mr-2 text-gray-400 hover:text-white"
            >
              <Menu size={24} />
            </button>
            <h1 className="font-black text-xl tracking-tighter md:hidden">NZ GPT</h1>
            <span className="hidden md:block font-bold text-gray-500 text-sm">
              {currentChatId ? 'محادثة الحالية' : 'محادثة جديدة'}
            </span>
          </div>

          <div className="flex items-center gap-4">
              {messages.length > 0 && (
                <button 
                  onClick={createNewChat} 
                  className="p-2 text-gray-500 hover:text-red-500 transition-colors active:scale-90"
                  title="مسح الشاشة (محادثة جديدة)"
                >
                  <Trash2 size={18} />
                </button>
              )}

              <div className="flex items-center gap-2 px-3 py-1 bg-white/5 rounded-full border border-white/10">
                <div className={`w-1.5 h-1.5 rounded-full shadow-[0_0_8px] ${isOnline ? 'bg-green-500 shadow-green-500/60' : 'bg-red-500 shadow-red-500/60'} animate-pulse`}></div>
                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{isOnline ? 'متصل' : 'غير متصل'}</span>
              </div>
          </div>
        </header>

        {/* Chat Area */}
        <main className="flex-1 overflow-y-auto w-full selection:bg-emerald-500/30">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500">
                <div className="w-20 h-20 mb-8 bg-white/5 rounded-[32px] flex items-center justify-center text-white/10 shadow-inner -rotate-6 border border-white/5">
                  <Sparkles size={48} />
                </div>
                <h2 className="text-3xl font-black text-white mb-4 tracking-tighter">مرحباً {user.displayName?.split(' ')[0]}</h2>
                <p className="text-gray-500 text-sm max-w-xs leading-relaxed font-medium">
                  {isGuest 
                    ? "أنا NZ GPT PRO. أنا هنا لمساعدتك في وضع الزائر." 
                    : "أنا NZ GPT PRO. تم حفظ محادثاتك بأمان. كيف يمكنني مساعدتك اليوم؟"
                  }
                </p>
            </div>
          ) : (
            <div className="w-full pb-6">
              {messages.map(msg => <MessageItem key={msg.id} message={msg} />)}
              {isLoading && (
                <div className="py-12 px-8">
                  <div className="max-w-3xl mx-auto flex gap-6 items-start">
                    <div className="w-10 h-10 rounded-[14px] bg-emerald-600 flex items-center justify-center shrink-0 shadow-2xl animate-pulse">
                      <Sparkles size={20} className="text-white" />
                    </div>
                    <div className="flex gap-2 mt-4">
                      <div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                      <div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
        </main>

        {/* Adsterra Banner */}
        <div 
          key={adRefreshKey}
          className="w-full flex justify-center bg-[#212121] py-1 shrink-0 border-t border-white/5"
          dangerouslySetInnerHTML={{ __html: `
            <iframe 
              srcdoc="<html><body style='margin:0;padding:0;background:transparent;display:flex;justify-content:center;align-items:center;'><script>atOptions = {'key' : '1306df10c9f2f6deae48cc2aa33f8f8e','format' : 'iframe','height' : 50,'width' : 320,'params' : {}};</script><script src='https://www.highperformanceformat.com/1306df10c9f2f6deae48cc2aa33f8f8e/invoke.js'></script></body></html>"
              width="320"
              height="50"
              style="border:none;overflow:hidden;"
              scrolling="no"
              frameborder="0"
            ></iframe>
          `}} 
        />

        {/* Input Area */}
        <div className="bg-[#212121] border-t border-white/5 p-4 safe-pb z-40 relative">
          <div className="max-w-3xl mx-auto relative">

            {selectedImage && (
              <div className="absolute -top-24 right-0 p-2 bg-[#2f2f2f] rounded-2xl border border-white/10 shadow-xl animate-in slide-in-from-bottom-5 z-50">
                <img src={selectedImage} className="h-14 w-14 object-cover rounded-xl" />
                <button onClick={() => setSelectedImage(null)} className="absolute -top-2 -left-2 bg-red-500 text-white rounded-full p-1 shadow-lg active:scale-90"><X size={12} /></button>
              </div>
            )}

            <div className="bg-[#2f2f2f] border border-white/10 rounded-[24px] shadow-lg flex items-end overflow-hidden focus-within:border-white/20 transition-all">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-3.5 text-gray-400 hover:text-white active:scale-90 transition-all shrink-0 self-center"
              >
                <Paperclip size={18} />
              </button>

              <input 
                type="file" 
                ref={fileInputRef} 
                accept="image/*" 
                onChange={handleImageUpload} 
                className="hidden" 
              />

              <textarea 
                ref={textareaRef}
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                placeholder="اكتب رسالتك..."
                className="flex-1 bg-transparent border-none focus:ring-0 text-[15px] py-3.5 px-1 min-h-[50px] max-h-32 text-white placeholder-gray-500 font-medium overflow-y-auto"
                rows={1}
                onInput={(e) => {
                  const target = e.target as HTMLTextAreaElement;
                  target.style.height = 'auto';
                  target.style.height = `${Math.min(target.scrollHeight, 128)}px`;
                }}
              />

              <div className="p-1.5 shrink-0 self-center">
                {isLoading || isStreaming ? (
                  <button onClick={() => abortControllerRef.current?.abort()} className="p-2.5 bg-white text-black rounded-full hover:bg-gray-100 shadow-md active:scale-90 transition-all">
                    <StopCircle size={16} />
                  </button>
                ) : (
                  <button 
                    onClick={() => handleSendMessage()}
                    disabled={!inputText.trim() && !selectedImage}
                    className={`p-2.5 rounded-full transition-all ${(!inputText.trim() && !selectedImage) ? 'text-gray-600 bg-transparent' : 'bg-emerald-600 text-white shadow-lg active:scale-90'}`}
                  >
                    <Send size={16} fill="currentColor" />
                  </button>
                )}
              </div>
            </div>

            <div className="flex justify-center mt-2">
               <p className="text-[8px] text-gray-600 font-bold tracking-[2px] uppercase opacity-40">NZ GPT PRO</p>
            </div>
          </div>
        </div>

      </div>

    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, X, WifiOff, StopCircle, Sparkles, Trash2, Heart, LogIn, LogOut, Menu, Plus, MessageSquare, History, AlertTriangle, User as UserIcon } from 'lucide-react';
import { Message, Role, UserProfile, ChatSession } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

// Firebase Imports
import { auth, googleProvider, db } from './firebaseConfig';
import { signInWithPopup, signOut, onAuthStateChanged, User } from 'firebase/auth';
import { collection, addDoc, query, where, orderBy, onSnapshot, doc, updateDoc, serverTimestamp, getDoc } from 'firebase/firestore';

function App() {
  // Authentication State
  const [user, setUser] = useState<User | any | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);

  // Chat State
  const [messages, setMessages] = useState<Message[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // UI State
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Modals & Ads
  const [showWelcomeModal, setShowWelcomeModal] = useState(false); // Default false, shown after login logic if needed
  const [adRefreshKey, setAdRefreshKey] = useState(0);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  // --- Authentication Monitor ---
  useEffect(() => {
    // If auth is not initialized (missing keys), just stop loading.
    // The user will see the login screen with buttons.
    if (!auth || !db) {
      setAuthLoading(false);
      return;
    }

    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);
      if (currentUser) {
        // Load user's chat history
        const q = query(
          collection(db!, "chats"), 
          where("userId", "==", currentUser.uid),
          orderBy("updatedAt", "desc")
        );
        const unsubscribeChats = onSnapshot(q, (snapshot) => {
          const history = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          } as ChatSession));
          setChatHistory(history);
        }, (error) => {
           console.error("Error fetching chats:", error);
        });
        return () => unsubscribeChats();
      } else {
        setChatHistory([]);
        setMessages([]);
        setCurrentChatId(null);
      }
    });
    return () => unsubscribe();
  }, []);

  // --- Network Monitor ---
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- Ad Timer ---
  useEffect(() => {
    const interval = setInterval(() => {
      setAdRefreshKey(prev => prev + 1);
    }, 30000); 
    return () => clearInterval(interval);
  }, []);

  // --- Auto Scroll ---
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isLoading]);

  // --- Handlers ---

  const handleGoogleLogin = async () => {
    if (!auth || !googleProvider) {
      alert("عذراً، لم يتم العثور على إعدادات Firebase. يرجى التحقق من ملف .env لتفعيل تسجيل الدخول.");
      return;
    }
    try {
      await signInWithPopup(auth, googleProvider);
    } catch (error) {
      console.error("Login failed", error);
      alert("فشل تسجيل الدخول. يرجى التحقق من اتصالك والمحاولة مرة أخرى.");
    }
  };

  const handleGuestLogin = () => {
    const guestUser = {
      uid: 'guest-' + Date.now(),
      displayName: 'Guest User',
      email: null,
      photoURL: null,
      isAnonymous: true
    };
    setIsGuest(true);
    setUser(guestUser);
  };

  const handleLogout = async () => {
    if (window.confirm("هل أنت متأكد من تسجيل الخروج؟")) {
      if (auth && !isGuest) {
        await signOut(auth);
      } else {
        setUser(null);
        setIsGuest(false);
        setMessages([]);
        setChatHistory([]);
      }
    }
  };

  const createNewChat = () => {
    setMessages([]);
    setCurrentChatId(null);
    setIsSidebarOpen(false);
    if (textareaRef.current) textareaRef.current.focus();
  };

  const loadChat = (session: ChatSession) => {
    setCurrentChatId(session.id);
    setMessages(session.messages);
    setIsSidebarOpen(false);
  };

  const deleteChat = async (e: React.MouseEvent, chatId: string) => {
    e.stopPropagation();
    if (window.confirm("هل تريد حذف هذه المحادثة نهائياً؟")) {
       try {
         if (db && !isGuest) {
             // await deleteDoc(doc(db, "chats", chatId)); 
             console.log("Delete requested for", chatId);
         }
       } catch (err) {
         console.error(err);
       }
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const saveChatToFirebase = async (updatedMessages: Message[], newMsgText: string) => {
    // If in guest mode or db not available, skip saving
    if (!user || !db || isGuest) return;

    try {
      if (!currentChatId) {
        // Create new chat document
        const title = newMsgText.length > 30 ? newMsgText.substring(0, 30) + "..." : newMsgText;
        const docRef = await addDoc(collection(db, "chats"), {
          userId: user.uid,
          title: title,
          messages: updatedMessages,
          createdAt: Date.now(),
          updatedAt: Date.now()
        });
        setCurrentChatId(docRef.id);
      } else {
        // Update existing chat
        const chatRef = doc(db, "chats", currentChatId);
        await updateDoc(chatRef, {
          messages: updatedMessages,
          updatedAt: Date.now()
        });
      }
    } catch (error) {
      console.error("Error saving chat:", error);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    if (!isOnline) return;

    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    // 1. Add User Message
    const userMsg: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    const updatedMessages = [...messages, userMsg];
    setMessages(updatedMessages);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

    setIsLoading(true);
    abortControllerRef.current = new AbortController();

    // Optimistic Save (Initial user message)
    if (user) saveChatToFirebase(updatedMessages, textToSend);

    try {
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;
      let finalBotText = "";

      await sendMessageToNZGPT(
        updatedMessages, 
        textToSend,
        (streamedText) => {
           finalBotText = streamedText;
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             setMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, text: streamedText, timestamp: Date.now() }]);
             isFirstChunk = false;
           } else {
             setMessages(prev => prev.map(msg => msg.id === botMsgId ? { ...msg, text: streamedText } : msg));
           }
        },
        tempImage || undefined,
        abortControllerRef.current.signal
      );

      // Final Save (Include Bot Response)
      if (user) {
        const messagesWithBot = [...updatedMessages, { id: botMsgId, role: Role.MODEL, text: finalBotText, timestamp: Date.now() }];
        saveChatToFirebase(messagesWithBot, textToSend);
      }

    } catch (error: any) {
      if (error.name !== 'AbortError') {
        const errorMessage = error.message.includes("API Key") 
          ? "عذراً، مفتاح الربط مع الذكاء الاصطناعي مفقود." 
          : "خطأ في الاتصال. تأكد من جودة الإنترنت.";

        setMessages(prev => [...prev, { id: Date.now().toString(), role: Role.MODEL, text: errorMessage, timestamp: Date.now() }]);
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };


  // --- Render: Login Screen ---
  if (authLoading) {
