            <div className="flex justify-center mt-2">
               <p className="text-[8px] text-gray-600 font-bold tracking-[2px] uppercase opacity-40">NZ GPT PRO</p>
            </div>
          </div>
        </div>

      </div>

    </div>
  );
}

