import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, X, StopCircle, Sparkles, Trash2, LogIn, LogOut, Menu, Plus, MessageSquare, History, AlertTriangle, User as UserIcon, CheckCircle, AlertCircle, ChevronDown } from 'lucide-react';
import { Message, Role, ChatSession } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

// Firebase Imports
import { auth, googleProvider, db, isFirebaseInitialized } from './firebaseConfig';
import { signInWithPopup, signOut, onAuthStateChanged, User } from 'firebase/auth';
import { collection, addDoc, query, where, onSnapshot, doc, updateDoc, deleteDoc, writeBatch, getDocs } from 'firebase/firestore';

// المكون الرسومي للوجو لضمان ظهوره دائماً بأعلى جودة
export const BrandLogo = ({ className = "w-24 h-24" }: { className?: string }) => (
  <svg className={className} viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
    <rect width="100" height="100" rx="25" fill="#10b981"/>
    <path d="M50 20C50 36.5 43.5 50 27 50C43.5 50 50 63.5 50 80C50 63.5 56.5 50 73 50C56.5 50 50 36.5 50 20Z" fill="white"/>
    <path d="M25 25V35M20 30H30" stroke="white" stroke-width="4" stroke-linecap="round"/>
    <path d="M75 65V75M70 70H80" stroke="white" stroke-width="4" stroke-linecap="round"/>
  </svg>
);

function App() {
  // Authentication State
  const [user, setUser] = useState<User | any | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);

  // Chat State
  const [messages, setMessages] = useState<Message[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);

  // UI State - Dropdowns
  const [showHistoryDropdown, setShowHistoryDropdown] = useState(false);
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);

  // UI State - General
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Notifications & Ads
  const [notification, setNotification] = useState<{message: string, type: 'error' | 'success'} | null>(null);
  const [adRefreshKey, setAdRefreshKey] = useState(0);
  const [messageCountForAds, setMessageCountForAds] = useState(0); 

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const historyDropdownRef = useRef<HTMLDivElement>(null);
  const profileDropdownRef = useRef<HTMLDivElement>(null);

  const showNotification = (message: string, type: 'error' | 'success' = 'error') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  useEffect(() => {
    if (!isFirebaseInitialized || !auth) {
      setAuthLoading(false);
      return;
    }

    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthLoading(false);

      if (currentUser && db) {
        const q = query(collection(db, "chats"), where("userId", "==", currentUser.uid));
        const unsubscribeChats = onSnapshot(q, (snapshot) => {
          const history = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as ChatSession));
          history.sort((a, b) => b.updatedAt - a.updatedAt);
          setChatHistory(history);
        });
        return () => unsubscribeChats();
      }
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isLoading]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (historyDropdownRef.current && !historyDropdownRef.current.contains(event.target as Node)) setShowHistoryDropdown(false);
      if (profileDropdownRef.current && !profileDropdownRef.current.contains(event.target as Node)) setShowProfileDropdown(false);
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleGoogleLogin = async () => {
    if (!isFirebaseInitialized || !auth || !googleProvider) return;
    try { await signInWithPopup(auth, googleProvider); } catch (e) { showNotification("فشل تسجيل الدخول"); }
  };

  const handleGuestLogin = () => {
    setUser({ uid: 'guest-' + Date.now(), displayName: 'زائر', photoURL: null });
    setIsGuest(true);
  };

  const handleLogout = async () => {
    if (window.confirm("خروج؟")) {
      if (auth && !isGuest) await signOut(auth);
      else { setUser(null); setIsGuest(false); }
    }
  };

  const createNewChat = () => { setMessages([]); setCurrentChatId(null); };

  const loadChat = (session: ChatSession) => {
    setCurrentChatId(session.id);
    setMessages(session.messages);
    setShowHistoryDropdown(false);
  };

  const handleSendMessage = async () => {
    if (!inputText.trim() && !selectedImage || isLoading || isStreaming) return;

    const nextMsgCount = messageCountForAds + 1;
    setMessageCountForAds(nextMsgCount);
    if (nextMsgCount % 3 === 0) setAdRefreshKey(prev => prev + 1);

    const userMsg: Message = { id: Date.now().toString(), role: Role.USER, text: inputText, image: selectedImage || undefined, timestamp: Date.now() };
    const updatedMessages = [...messages, userMsg];
    setMessages(updatedMessages);
    setInputText('');
    const tempImg = selectedImage;
    setSelectedImage(null);
    setIsLoading(true);

    abortControllerRef.current = new AbortController();

    try {
      const botMsgId = (Date.now() + 100).toString();
      let isFirst = true;
      await sendMessageToNZGPT(updatedMessages, userMsg.text, (streamed) => {
        if (isFirst) {
          setIsLoading(false); setIsStreaming(true);
          setMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, text: streamed, timestamp: Date.now() }]);
          isFirst = false;
        } else {
          setMessages(prev => prev.map(m => m.id === botMsgId ? { ...m, text: streamed } : m));
        }
      }, tempImg || undefined, abortControllerRef.current.signal);
    } catch (e) {
      setIsLoading(false);
    } finally { setIsStreaming(false); }
  };

  if (authLoading) return <div className="h-screen w-screen bg-[#212121] flex items-center justify-center"><BrandLogo className="w-16 h-16 animate-pulse" /></div>;

  if (!user) {
    return (
      <div className="flex flex-col h-screen w-screen bg-[#212121] items-center justify-center p-6 relative overflow-hidden">
        <div className="z-10 bg-[#2a2a2a] border border-white/5 p-10 rounded-[40px] shadow-2xl max-w-md w-full text-center">
          <div className="mb-8 transform rotate-3 hover:rotate-0 transition-transform duration-500 flex justify-center">
             <BrandLogo className="w-28 h-28 shadow-2xl rounded-[30px]" />
          </div>
          <h1 className="text-4xl font-black text-white mb-2 tracking-tighter">NZ GPT PRO</h1>
          <p className="text-gray-400 mb-10 font-medium">نظام المحادثة الذكي المتطور</p>
          <div className="flex flex-col gap-4">
            <button onClick={handleGoogleLogin} className="w-full bg-white text-gray-900 font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-xl hover:bg-gray-50 active:scale-95 transition-all">المتابعة باستخدام Google</button>
            <button onClick={handleGuestLogin} className="w-full font-bold py-4 rounded-2xl flex items-center justify-center gap-3 bg-white/5 hover:bg-white/10 text-white border border-white/10 active:scale-95 transition-all">تجربة كزائر</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen w-screen bg-[#212121] text-gray-100 overflow-hidden relative">
        <header className="flex flex-row-reverse items-center justify-between px-6 py-4 bg-[#171717] border-b border-white/5 shrink-0 z-50">
            <div className="flex items-center gap-4">
                <button onClick={createNewChat} className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-5 py-2.5 rounded-2xl transition-all active:scale-95 shadow-lg"><Plus size={20} /><span className="text-sm font-bold hidden sm:inline">محادثة جديدة</span></button>
                <div className="relative" ref={profileDropdownRef}>
                    <button onClick={() => setShowProfileDropdown(!showProfileDropdown)} className="w-10 h-10 rounded-full border-2 border-white/10 overflow-hidden hover:border-emerald-500 transition-all">
                        <img src={user.photoURL || `https://ui-avatars.com/api/?name=${user.displayName}&background=random`} className="w-full h-full object-cover" />
                    </button>
                    {showProfileDropdown && (
                        <div className="absolute top-full right-0 mt-3 w-60 bg-[#1a1a1a] border border-white/10 rounded-2xl shadow-2xl z-[100] p-2">
                            <div className="p-3 border-b border-white/5 mb-1"><p className="text-sm font-bold truncate">{user.displayName}</p></div>
                            <button onClick={handleLogout} className="w-full flex items-center gap-2 p-3 text-sm text-red-400 hover:bg-red-500/10 rounded-xl transition-colors"><LogOut size={16} /><span>تسجيل الخروج</span></button>
                        </div>
                    )}
                </div>
            </div>
            <div className="flex items-center gap-4">
                 <div className="relative" ref={historyDropdownRef}>
                    <button onClick={() => setShowHistoryDropdown(!showHistoryDropdown)} className="p-2.5 bg-white/5 rounded-xl text-gray-400 hover:text-white transition-all"><History size={22} /></button>
                    {showHistoryDropdown && (
                        <div className="absolute top-full left-0 mt-3 w-80 max-h-[70vh] bg-[#1a1a1a] border border-white/10 rounded-2xl shadow-2xl overflow-y-auto z-[100]">
                            <div className="p-4 border-b border-white/5 sticky top-0 bg-[#1a1a1a] font-bold text-xs text-gray-500">المحادثات السابقة</div>
                            <div className="p-2 space-y-1">
                                {chatHistory.length ? chatHistory.map(c => (
                                    <div key={c.id} onClick={() => loadChat(c)} className="p-3 rounded-xl hover:bg-white/5 cursor-pointer flex items-center gap-3 transition-colors">
                                        <MessageSquare size={16} className="text-emerald-500" />
                                        <span className="text-sm truncate flex-1 text-right">{c.title}</span>
                                    </div>
                                )) : <div className="p-8 text-center text-xs text-gray-600">لا يوجد سجل</div>}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </header>

      <main className="flex-1 overflow-y-auto w-full">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-700">
                <div className="mb-8 -rotate-6 transform hover:rotate-0 transition-transform duration-500">
                   <BrandLogo className="w-32 h-32 shadow-2xl rounded-[40px] border border-white/10" />
                </div>
                <h2 className="text-4xl font-black text-white mb-4 tracking-tighter">مرحباً {user.displayName?.split(' ')[0]}</h2>
                <p className="text-gray-500 text-sm max-w-xs leading-relaxed font-medium">أنا NZ GPT PRO. كيف يمكنني مساعدتك اليوم في برمجياتك؟</p>
            </div>
          ) : (
            <div className="w-full pb-10">
              {messages.map(msg => <MessageItem key={msg.id} message={msg} />)}
              {isLoading && (
                <div className="py-12 px-8 max-w-3xl mx-auto flex gap-6 items-start">
                    <BrandLogo className="w-10 h-10 rounded-xl shrink-0 animate-pulse" />
                    <div className="flex gap-2 mt-4"><div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce"></div><div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce [animation-delay:0.2s]"></div><div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce [animation-delay:0.4s]"></div></div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
      </main>

      <div key={adRefreshKey} className="w-full flex justify-center bg-[#212121] py-1 border-t border-white/5 shrink-0" dangerouslySetInnerHTML={{ __html: `<iframe srcdoc="<html><body style='margin:0;padding:0;display:flex;justify-content:center;'><script>atOptions={'key':'1306df10c9f2f6deae48cc2aa33f8f8e','format':'iframe','height':50,'width':320,'params':{}};</script><script src='https://www.highperformanceformat.com/1306df10c9f2f6deae48cc2aa33f8f8e/invoke.js'></script></body></html>" width="320" height="50" style="border:none" scrolling="no"></iframe>`}} />

      <div className="bg-[#212121] border-t border-white/5 p-5 safe-pb">
          <div className="max-w-3xl mx-auto relative">
            {selectedImage && (
              <div className="absolute -top-24 right-0 p-2 bg-[#2f2f2f] rounded-2xl border border-white/10 shadow-2xl animate-in slide-in-from-bottom-5">
                <img src={selectedImage} className="h-16 w-16 object-cover rounded-xl" />
                <button onClick={() => setSelectedImage(null)} className="absolute -top-2 -left-2 bg-red-500 text-white rounded-full p-1"><X size={12} /></button>
              </div>
            )}
            <div className="bg-[#2f2f2f] border border-white/10 rounded-[28px] shadow-2xl flex items-end overflow-hidden focus-within:border-emerald-500/50 transition-all p-1">
              <button onClick={() => fileInputRef.current?.click()} className="p-4 text-gray-400 hover:text-white transition-all"><Paperclip size={20} /></button>
              <input type="file" ref={fileInputRef} accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if(f){ const r = new FileReader(); r.onloadend = () => setSelectedImage(r.result as string); r.readAsDataURL(f); } }} className="hidden" />
              <textarea ref={textareaRef} value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())} placeholder="اكتب رسالتك لـ NZ GPT..." className="flex-1 bg-transparent border-none focus:ring-0 text-[16px] py-4 px-2 min-h-[56px] max-h-40 text-white placeholder-gray-500 font-medium resize-none" rows={1} />
              <div className="p-1">
                {isLoading || isStreaming ? (
                  <button onClick={() => abortControllerRef.current?.abort()} className="p-3.5 bg-white text-black rounded-full hover:bg-gray-100"><StopCircle size={20} /></button>
                ) : (
                  <button onClick={handleSendMessage} disabled={!inputText.trim() && !selectedImage} className={`p-3.5 rounded-full transition-all ${(!inputText.trim() && !selectedImage) ? 'text-gray-600' : 'bg-emerald-600 text-white'}`}><Send size={20} fill="currentColor" /></button>
                )}
              </div>
            </div>
            <p className="text-center mt-3 text-[9px] text-gray-600 font-black tracking-[3px] uppercase opacity-40">Powered by NZ GPT PRO</p>
          </div>
      </div>
    </div>
  );
}

export default App;

import React from 'react';
import { Message, Role } from '../types';
import { ExternalLink, User } from 'lucide-react';
import CodeBlock from './CodeBlock';
import { BrandLogo } from '../App';

interface MessageItemProps {
  message: Message;
}

const MessageItem: React.FC<MessageItemProps> = ({ message }) => {
  const isUser = message.role === Role.USER;

  const renderInlineStyles = (text: string) => {
    const parts = text.split(/(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/g);
    return parts.map((part, index) => {
      if (part.startsWith('`') && part.endsWith('`')) {
        return <code key={index} className="bg-white/10 text-gray-200 px-1.5 py-0.5 rounded text-[13px] font-mono mx-0.5" dir="ltr">{part.slice(1, -1)}</code>;
      }
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={index} className="font-bold text-white">{part.slice(2, -2)}</strong>;
      }
      if (part.startsWith('[') && part.includes('](') && part.endsWith(')')) {
        const match = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
        if (match) {
          return (
            <a key={index} href={match[2]} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:underline inline-flex items-center gap-0.5 mx-1">
              {match[1]} <ExternalLink size={10} />
            </a>
          );
        }
      }
      return part;
    });
  };

  const renderContent = (fullText: string) => {
    const parts = fullText.split(/(```[\s\S]*?```|```[\s\S]*$)/g);
    return parts.map((part, index) => {
      if (part.startsWith('```')) {
        let content = part.slice(3);
        if (content.endsWith('```')) content = content.slice(0, -3);
        const firstLineBreak = content.indexOf('\n');
        let language = 'code';
        let code = content;
        if (firstLineBreak > -1) {
            const potentialLang = content.substring(0, firstLineBreak).trim();
            if (potentialLang.length < 15 && !potentialLang.includes(' ')) {
                language = potentialLang || 'code';
                code = content.substring(firstLineBreak + 1);
            }
        }
        return <CodeBlock key={index} code={code.trim()} language={language} />;
      }

      if (part.trim() === '') return null;

      return (
        <div key={index} className="space-y-4">
          {part.split('\n').map((line, i) => {
            if (!line.trim()) return <div key={i} className="h-2"></div>;
            if (line.startsWith('### ')) return <h3 key={i} className="text-lg font-black text-white mt-6 mb-2 leading-tight">{renderInlineStyles(line.replace(/^###\s+/, ''))}</h3>;
            if (line.startsWith('## ')) return <h2 key={i} className="text-xl font-black text-white mt-8 mb-4 leading-tight">{renderInlineStyles(line.replace(/^##\s+/, ''))}</h2>;
            if (line.match(/^[\-\*]\s/)) return <div key={i} className="flex gap-3 pr-2"><span className="text-gray-500 mt-2 text-[6px]">●</span><span className="text-gray-300 flex-1 leading-relaxed text-[15px]">{renderInlineStyles(line.replace(/^[\-\*]\s+/, ''))}</span></div>;
            if (line.match(/^\d+\.\s/)) return <div key={i} className="flex gap-3 pr-1"><span className="text-gray-500 font-mono text-sm mt-0.5">{line.match(/^\d+/)?.[0]}.</span><span className="text-gray-300 flex-1 leading-relaxed text-[15px]">{renderInlineStyles(line.replace(/^\d+\.\s+/, ''))}</span></div>;
            return <p key={i} className="leading-relaxed text-[#f0f0f0] text-[15px]">{renderInlineStyles(line)}</p>;
          })}
        </div>
      );
    });
  };

  return (
    <div className={`w-full py-10 px-4 md:px-6 border-b border-white/[0.03] animate-in fade-in slide-in-from-bottom-2 duration-300`}>
      <div className="max-w-3xl mx-auto flex gap-4 md:gap-6 items-start">
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 border shadow-md overflow-hidden ${
          isUser ? 'bg-[#3f3f3f] border-white/10 text-white' : 'bg-transparent border-emerald-500/20'
        }`}>
          {isUser ? <User size={20} /> : <BrandLogo className="w-full h-full" />}
        </div>
        <div className="flex-1 min-w-0 pt-0.5">
          <p className="text-[11px] font-black uppercase tracking-[2px] text-gray-500 mb-3">{isUser ? 'أنت' : 'NZ GPT PRO'}</p>
          <div className="text-[16px] selection:bg-emerald-500/20">
            {message.image && <div className="mb-5 rounded-2xl overflow-hidden border border-white/10 shadow-2xl inline-block"><img src={message.image} alt="Upload" className="max-w-full h-auto max-h-[400px] object-contain" /></div>}
            <div className="overflow-x-auto">
