              <input type="file" ref={fileInputRef} accept="image/*" onChange={(e) => { const f = e.target.files?.[0]; if(f){ const r = new FileReader(); r.onloadend = () => setSelectedImage(r.result as string); r.readAsDataURL(f); } }} className="hidden" />
              <textarea ref={textareaRef} value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())} placeholder="اكتب رسالتك لـ NZ GPT..." className="flex-1 bg-transparent border-none focus:ring-0 text-[16px] py-4 px-2 min-h-[56px] max-h-40 text-white placeholder-gray-500 font-medium resize-none" rows={1} />
