                {isLoading || isStreaming ? (
                  <button onClick={() => abortControllerRef.current?.abort()} className="p-3.5 bg-white text-black rounded-full hover:bg-gray-100"><StopCircle size={20} /></button>
                ) : (
                  <button onClick={handleSendMessage} disabled={!inputText.trim() && !selectedImage} className={`p-3.5 rounded-full transition-all ${(!inputText.trim() && !selectedImage) ? 'text-gray-600' : 'bg-emerald-600 text-white'}`}><Send size={20} fill="currentColor" /></button>
                )}
              </div>
            </div>
            <p className="text-center mt-3 text-[9px] text-gray-600 font-black tracking-[3px] uppercase opacity-40">Powered by NZ GPT PRO</p>
          </div>
      </div>
    </div>
  );
}

